"use strict";

const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
  "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const BROWSER_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not-A.Brand";v="99"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "sec-fetch-user": "?1",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? u.replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorbSetCookie(list) {
    if (!Array.isArray(list)) return;
    for (const c of list) {
      const kv = String(c).split(";")[0];
      const i = kv.indexOf("=");
      if (i > 0) this.map.set(kv.slice(0, i).trim(), kv.slice(i + 1).trim());
    }
  }
  absorbFetch(res) {
    if (res && res.headers && typeof res.headers.getSetCookie === "function") {
      this.absorbSetCookie(res.headers.getSetCookie());
    }
  }
  absorbNodeHeaders(headers) {
    if (!headers) return;
    const sc = headers["set-cookie"];
    if (sc) this.absorbSetCookie(Array.isArray(sc) ? sc : [sc]);
  }
  header() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function httpsGetText(targetUrl, jar, headers, redirectsLeft) {
  return new Promise((resolve, reject) => {
    let u;
    try {
      u = new URL(targetUrl);
    } catch {
      reject(new Error("Invalid URL: " + targetUrl));
      return;
    }
    const req = https.get(
      {
        hostname: u.hostname,
        path: u.pathname + u.search,
        headers: {
          ...headers,
          ...(jar.map.size ? { cookie: jar.header() } : {}),
        },
        timeout: 30000,
      },
      (res) => {
        jar.absorbNodeHeaders(res.headers);
        if (
          res.statusCode >= 300 &&
          res.statusCode < 400 &&
          res.headers.location &&
          redirectsLeft > 0
        ) {
          res.resume();
          const next = new URL(res.headers.location, targetUrl).toString();
          resolve(httpsGetText(next, jar, headers, redirectsLeft - 1));
          return;
        }
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({ html: Buffer.concat(chunks).toString("utf8"), finalUrl: targetUrl })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Facebook page request timed out")));
    req.on("error", reject);
  });
}

async function fetchPage(targetUrl, jar, headers) {
  if (typeof fetch === "function") {
    const res = await fetch(targetUrl, {
      headers: {
        ...(headers || BROWSER_HEADERS),
        ...(jar && jar.map.size ? { cookie: jar.header() } : {}),
      },
      redirect: "follow",
    });
    if (jar) jar.absorbFetch(res);
    const html = await res.text();
    return { html, finalUrl: res.url || targetUrl };
  }
  return httpsGetText(targetUrl, jar || new Jar(), headers || BROWSER_HEADERS, 5);
}

const STR = '((?:\\\\.|[^"\\\\])*)';
const re = (src) => new RegExp(src);

function decodeJsonString(captured) {
  try {
    return JSON.parse(`"${captured}"`);
  } catch {
    return captured;
  }
}

function grab(html, regex) {
  const m = html.match(regex);
  return m ? decodeJsonString(m[1]) : null;
}

function grabNum(html, regex) {
  const m = html.match(regex);
  return m ? Number(m[1]) : null;
}

async function fetchWatchPage(id, jar, tries = 6) {
  const url = `https://www.facebook.com/watch/?v=${id}`;
  let last = null;
  for (let i = 0; i < tries; i++) {
    const { html } = await fetchPage(url, jar, BROWSER_HEADERS);
    last = html;
    if (html.includes("browser_native_hd_url") || html.includes("browser_native_sd_url")) {
      return html;
    }
    await new Promise((r) => setTimeout(r, 900));
  }
  return last;
}

async function extractVideoId(input, jar) {
  const s = String(input).trim();
  if (/^\d{5,}$/.test(s)) return s;
  const direct =
    s.match(/[?&]v=(\d{5,})/) ||
    s.match(/\/reel\/(\d{5,})/) ||
    s.match(/\/videos\/(?:[^/]+\/)?(\d{5,})/) ||
    s.match(/\/watch\/(\d{5,})/);
  if (direct) return direct[1];
  if (/fb\.watch|facebook\.com\/share\//.test(s)) {
    const { html, finalUrl } = await fetchPage(s, jar, BROWSER_HEADERS);
    const m =
      finalUrl.match(/[?&]v=(\d{5,})/) || finalUrl.match(/\/reel\/(\d{5,})/);
    if (m) return m[1];
    const og = html.match(/facebook\.com\/watch\/\?v=(\d{5,})/);
    if (og) return og[1];
  }
  throw new Error("Could not find a Facebook video id in that URL");
}

function parseAuthor(html) {
  const idx = html.indexOf('"actors":[');
  if (idx < 0) return null;
  const w = html.slice(idx, idx + 1600);
  return {
    id: grab(w, re('"id":"(\\d+)"')) || grabNum(w, re('"id":(\\d+)'))?.toString() || null,
    name: grab(w, re(`"name":"${STR}"`)),
    url: grab(w, re(`"url":"${STR}"`)),
    avatar:
      grab(w, re(`"profile_picture":\\{"uri":"${STR}"`)) ||
      grab(w, re(`"profilePic":\\{"uri":"${STR}"`)) ||
      null,
  };
}

function parseComments(html, limit = 20) {
  const out = [];
  const bodyRe = new RegExp(`"body":\\{"text":"${STR}"`, "g");
  let m;
  while ((m = bodyRe.exec(html)) !== null && out.length < limit) {
    const text = decodeJsonString(m[1]);
    if (!text) continue;
    const before = html.slice(Math.max(0, m.index - 2000), m.index);
    const after = html.slice(m.index, m.index + 1200);
    const nameMatches = [...before.matchAll(new RegExp(`"name":"${STR}"`, "g"))];
    const idMatches = [...before.matchAll(/"legacy_fbid":"(\d+)"/g)];
    const created = grabNum(after, /"created_time":(\d+)/);
    const reactions = grabNum(after, /"reaction_count":\{"count":(\d+)/);
    out.push({
      id: idMatches.length ? idMatches[idMatches.length - 1][1] : null,
      author: nameMatches.length
        ? decodeJsonString(nameMatches[nameMatches.length - 1][1])
        : null,
      text,
      createdTime: created,
      reactions,
    });
  }
  return out;
}

function parseVideo(html, id, sourceUrl) {
  const hd = grab(html, re(`"browser_native_hd_url":"${STR}"`));
  const sd = grab(html, re(`"browser_native_sd_url":"${STR}"`));
  const ogTitle = grab(html, /<meta property="og:title" content="([^"]*)"/);
  const ogImage = grab(html, /<meta property="og:image" content="([^"]*)"/);
  const ogDesc = grab(html, /<meta property="og:description" content="([^"]*)"/);
  const decodeMeta = (s) =>
    s
      ? s
          .replace(/&amp;/g, "&")
          .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
          .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
      : s;

  let reactions = null;
  let commentsCount = null;
  const ri = html.indexOf('"i18n_reaction_count"');
  if (ri >= 0) {
    reactions = grabNum(html.slice(ri, ri + 500), /"reaction_count":\{"count":(\d+)/);
  }
  if (reactions == null) reactions = grabNum(html, /"reaction_count":\{"count":(\d+)/);
  const ci = html.indexOf('"comment_rendering_instance"');
  if (ci >= 0) {
    commentsCount = grabNum(html.slice(ci, ci + 400), /"comments":\{"total_count":(\d+)/);
  }
  if (commentsCount == null) commentsCount = grabNum(html, /"total_comment_count":(\d+)/);

  const caption = grab(html, re(`"message":\\{"text":"${STR}"`));
  const durationMs = grabNum(html, /"playable_duration_in_ms":(\d+)/);

  return {
    id,
    url: `https://www.facebook.com/watch/?v=${id}`,
    sourceUrl,
    type: /\/reel\//.test(sourceUrl || "") ? "reel" : "video",
    title: caption ? caption.split("\n")[0].slice(0, 200) : decodeMeta(ogTitle),
    caption: caption || decodeMeta(ogDesc) || null,
    thumbnail:
      grab(html, re(`"preferred_thumbnail":\\{"image":\\{"uri":"${STR}"`)) ||
      decodeMeta(ogImage) ||
      null,
    durationSeconds: durationMs != null ? Math.round(durationMs / 1000) : null,
    views: grabNum(html, /"play_count":(\d+)/),
    reactions,
    commentsCount,
    shares: grabNum(html, /"share_count":\{"count":(\d+)/),
    createdTime:
      grabNum(html, /"creation_time":(\d+)/) || grabNum(html, /"publish_time":(\d+)/),
    author: parseAuthor(html),
    download: { hd, sd },
    comments: parseComments(html),
  };
}

function seedJar(jar, cookie) {
  if (!cookie || typeof cookie !== "string") return;
  for (const part of cookie.split(";")) {
    const i = part.indexOf("=");
    if (i > 0) jar.map.set(part.slice(0, i).trim(), part.slice(i + 1).trim());
  }
}

async function getVideo(input, cookie) {
  const jar = new Jar();
  seedJar(jar, cookie);
  const id = await extractVideoId(input, jar);
  const html = await fetchWatchPage(id, jar);
  if (!html) throw new Error("Facebook returned an empty page");
  const data = parseVideo(html, id, String(input));
  if (!data.download.hd && !data.download.sd) {
    throw new Error(
      "No download URLs found — the video may be private, removed, or Facebook served a limited page. Try again."
    );
  }
  return data;
}

module.exports = async function fetchSelf(url, cookie) {
  if (!url || typeof url !== "string") {
    throw new Error("Facebook self-scrape failed: a Facebook video URL is required");
  }
  let data;
  try {
    data = await getVideo(url, cookie);
  } catch (e) {
    if (e && /^Facebook self-scrape failed:/.test(e.message || "")) throw e;
    throw new Error(
      "Facebook self-scrape failed: " + (e && e.message ? e.message : String(e))
    );
  }
  if (!data || (!data.download.hd && !data.download.sd)) {
    throw new Error(
      "Facebook self-scrape failed: No download URLs found — the video may be private, removed, or Facebook served a limited page. Try again."
    );
  }

  return {
    success: true,
    source: "Facebook",
    data: {
      title: data.title || "Facebook Video",
      thumbnail: data.thumbnail || null,
      download: {
        hd: cleanUrl(data.download.hd),
        sd: cleanUrl(data.download.sd),
      },
    },
  };
};
